"use strict";(self.webpackChunkrentparty_docs=self.webpackChunkrentparty_docs||[]).push([["5461"],{5602(e){e.exports=JSON.parse('{"tag":{"label":"Compare","permalink":"/tags/compare-tag","description":"How Rent Party differs from other games, and how to get a table going.","allTagsPath":"/tags","count":12,"items":[{"id":"compare/jackbox-party-packs","title":"Moving from a Jackbox Party Pack to Rent Party","description":"Jackbox packs are quick rounds on a shared screen, and Rent Party is one long game. Keep both for different nights. How to start, with dated facts on both.","permalink":"/compare/jackbox-party-packs"},{"id":"compare/board-game-arena","title":"Moving from Board Game Arena to Rent Party","description":"Board Game Arena has hundreds of games and Rent Party has one. When that one is the right pick, how to start a game over days, and dated facts on both.","permalink":"/compare/board-game-arena"},{"id":"compare/business-tour","title":"Moving from Business Tour to Rent Party","description":"Business Tour has a map editor and Rent Party doesn\'t yet. What you give up, how to get a table going in a browser, and the dated facts on both games.","permalink":"/compare/business-tour"},{"id":"compare/get-rent","title":"Moving from Get Rent to Rent Party","description":"Get Rent\'s board is the real world and Rent Party\'s is one table with friends. They\'re different games, so here\'s what changes and how to start, with dated facts.","permalink":"/compare/get-rent"},{"id":"compare/ludo-king","title":"Moving from Ludo King to Rent Party","description":"Ludo King is a ten-minute race game with ads, and Rent Party is a longer night of deeds. How to teach the family, how to start, and dated facts on both.","permalink":"/compare/ludo-king"},{"id":"compare/quadropoly","title":"Moving from Quadropoly to Rent Party","description":"Quadropoly is built around solo play with eight AI levels. What Rent Party\'s CPU characters offer instead, how to bring friends in, and the dated facts on both.","permalink":"/compare/quadropoly"},{"id":"compare/rento","title":"Moving from Rento to Rent Party","description":"Nothing carries over from Rento, and nothing needs to. How to get your Rento crew to a Rent Party table in a browser, with the dated facts on both games.","permalink":"/compare/rento"},{"id":"compare/richup-io","title":"Moving from Richup.io to Rent Party","description":"Both games open in a browser, so moving from Richup.io takes one link. What stays behind, how to start a room for friends, and the dated facts on both.","permalink":"/compare/richup-io"},{"id":"compare/rumble-avenue","title":"Moving from Rumble Avenue to Rent Party","description":"Rumble Avenue asks for no account, and Rent Party only asks for one online. How to get a table going, and the dated facts on both games.","permalink":"/compare/rumble-avenue"},{"id":"compare/tabletop-simulator","title":"Moving from Tabletop Simulator to Rent Party","description":"Tabletop Simulator is a PC sandbox every player buys. Rent Party opens in a browser with the rules built in. What changes, how to start, and dated facts on both.","permalink":"/compare/tabletop-simulator"},{"id":"compare/tabletopia","title":"Moving from Tabletopia to Rent Party","description":"On Tabletopia your group moves the pieces and keeps the rules. On Rent Party the game does that. What you give up, how to start, and dated facts on both.","permalink":"/compare/tabletopia"},{"id":"compare/index","title":"Moving to Rent Party from another game","description":"How Rent Party differs from eleven other games, what stays behind when you try it, and how to get a table going. Every price and row is dated and sourced.","permalink":"/compare/"}],"unlisted":false}}')}}]);